    }
}

/* ============================================================
   TG Glass — Round 4: 弹出动效（优雅高级版）
   设计原则（Apple/高级感范式）：
   - 运动幅度极小：scale 差 ≤0.02、位移 ≤4px——克制即高级
   - opacity 主导变化，transform 只做陪衬
   - 统一曲线 cubic-bezier(0.32, 0.72, 0, 1)（iOS sheet 曲线：
     快起 + 长缓收 = "毫不费力"的从容感）
   - 节奏不赶：入场 360-420ms，出场轻快但不急促
   ============================================================ */

/* ---------- 1. 弹窗 keyframes（优雅版） ----------
   opacity 淡入为主，scale 0.98→1 与 4px 上浮是若有似无的衬托 */

@keyframes pop-in {
    0% {
        opacity: 0;
        transform: scale(0.982) translateY(4px);
    }

    100% {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}

@keyframes pop-out {
    0% {
        opacity: 1;
        transform: scale(1) translateY(0);
    }

    100% {
        opacity: 0;
        transform: scale(0.992) translateY(2px);
    }
}

/* 弹窗曲线：入场 iOS sheet 曲线，出场轻柔收敛 */
.popup[opening] {
    animation: pop-in var(--popup-animation-speed) cubic-bezier(0.32, 0.72, 0, 1) !important;
}

.popup[closing] {
    animation: pop-out 280ms cubic-bezier(0.4, 0, 0.2, 1) !important;
}

/* 背景遮罩：缓慢渐显渐隐（高级感的呼吸，不是闪烁） */
.popup[opening]::backdrop {
    animation: fade-in var(--popup-animation-speed) cubic-bezier(0.3, 0.9, 0.3, 1) !important;
}

.popup[closing]::backdrop {
    animation: fade-out 280ms cubic-bezier(0.4, 0, 0.2, 1) !important;
}

/* 入场节奏：420ms 从容（太快显得廉价急躁） */
.popup:not(.popup--animation-fast):not(.popup--animation-slow):not(.popup--animation-none) {
    --popup-animation-speed: 420ms;
}

/* ---------- 2. 原生下拉菜单浮现（#options / #extensionsMenu） ----------
   纯淡入 + 3px 微沉浮，无缩放（缩放是"活力"感的来源） */

#options,
#extensionsMenu {
    animation: tg-menu-fade 340ms cubic-bezier(0.32, 0.72, 0, 1);
}

#options .options-content,
#extensionsMenu .list-group {
    animation: tg-menu-in 340ms cubic-bezier(0.32, 0.72, 0, 1);
}

@keyframes tg-menu-fade {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@keyframes tg-menu-in {
    from {
        opacity: 0;
        transform: translateY(-3px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ---------- 3. 抽屉面板内容浮现（同曲线同节奏） ---------- */

.drawer-content.openDrawer {
    animation: tg-menu-in 360ms cubic-bezier(0.32, 0.72, 0, 1);
}

/* ---------- 4. 手风琴：内容滑入联动 ----------
   高度由 jQuery slideToggle 驱动，这里叠加 3px 归位位移 */

.inline-drawer>.inline-drawer-content {
    transition: transform 320ms cubic-bezier(0.32, 0.72, 0, 1);
}

.inline-drawer:has(>.inline-drawer-header .inline-drawer-icon.up)>.inline-drawer-content {
    transform: translateY(0);
}

.inline-drawer:has(>.inline-drawer-header .inline-drawer-icon.down)>.inline-drawer-content {
    transform: translateY(-3px);
}

/* ---------- 5. 折叠箭头：180° 匀滑旋转 ----------
   旋转慢而匀（无回弹），像精密仪器 */

.inline-drawer-header .inline-drawer-icon.up {
    animation: tg-chevron-in 340ms cubic-bezier(0.32, 0.72, 0, 1);
}

.inline-drawer-header .inline-drawer-icon.down {
    animation: tg-chevron-out 300ms cubic-bezier(0.32, 0.72, 0, 1);
}

@keyframes tg-chevron-in {
    from {
        transform: rotate(180deg);
    }

    to {
        transform: rotate(0deg);
    }
}

@keyframes tg-chevron-out {
    from {
        transform: rotate(-180deg);
    }

    to {
        transform: rotate(0deg);
    }
}

/* ---------- 6. select2 下拉面板入场 ----------
   3px 上浮 + 极轻缩放，340ms 从容 ---------- */

.select2-dropdown {
    transform-origin: top center;
    animation: tg-dropdown-in 340ms cubic-bezier(0.32, 0.72, 0, 1);
}

@keyframes tg-dropdown-in {
    from {
        opacity: 0;
        transform: translateY(-3px) scaleY(0.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scaleY(1);
    }
}

/* ---------- 7. Toast 通知入场：缓慢上滑浮现 ---------- */

body #toast-container>div {
    animation: tg-toast-in 420ms cubic-bezier(0.32, 0.72, 0, 1);
}

@keyframes tg-toast-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ---------- 8. 主抽屉开合：iOS sheet 曲线（开启与关闭同曲线） ---------- */

.drawer-content {
    transition-timing-function: cubic-bezier(0.32, 0.72, 0, 1) !important;
}

.drawer-content.openDrawer {
    transition-timing-function: cubic-bezier(0.32, 0.72, 0, 1) !important;
}

/* ---------- 9. 角色面板等固定弹层的入场 ---------- */

#dialogue_popup,
.dialogue_popup {
    animation: pop-in 360ms cubic-bezier(0.32, 0.72, 0, 1);
}

/* ---------- 10. 减动效偏好 ---------- */

@media (prefers-reduced-motion: reduce) {

    .popup[opening],
    .popup[closing],
    .inline-drawer>.inline-drawer-content,
    .inline-drawer-header .inline-drawer-icon.up,
    .inline-drawer-header .inline-drawer-icon.down,
    .select2-dropdown,
    body #toast-container>div,
    #dialogue_popup,
    .dialogue_popup,
    #options,
    #extensionsMenu,
    #options .options-content,
    #extensionsMenu .list-group,
    .drawer-content.openDrawer {
        animation: none !important;
        transition: none !important;
    }
}

/* ============================================================
   TG Glass — Round 5: 性能层（LiteMode 思路）
   三个卡顿源（均为 GPU 合成成本，非动画/源码限制）：
   1. 抽屉高度动画期间 backdrop-filter 逐帧重渲染
      → TG 源码 LiteMode.FLAG_BLUR 的官方答案：动画表面实色
   2. 聊天文字全量 text-shadow，滚动时逐字形重绘
   3. 大尺寸背景纹理 + 多层 blur 叠加（移动端尤甚）
   策略：静态小表面保留 blur（顶栏/输入区），
        动画/大表面换高不透明度实色（TG Android 同款），
        移动端进一步降级
   ============================================================ */

/* ---------- 1. 聊天区文字阴影：砍掉逐字形重绘 ----------
   ST 默认给每条消息文字加 text-shadow 保证可读性，
   代价是滚动时每个字形都要画两次。
   TG Android 从不给正文加阴影——我们的玻璃底色已保证可读 */

#chat {
    text-shadow: none !important;
}

/* ---------- 2. 抽屉面板：真磨砂玻璃（撤销实色化） ----------
   手机端实测：实色 0.93 面板把壁纸整个盖住 → 毛玻璃不可见。
   改回半透明玻璃：blur 采样壁纸 + 酒红 tint + TG 细噪点颗粒
   （噪点即 TG 磨砂的触感签名——即使背后是平暗区也能读出玻璃面） */

.drawer-content {
    backdrop-filter: blur(26px) saturate(1.25) !important;
    -webkit-backdrop-filter: blur(26px) saturate(1.25) !important;
    background-color: rgba(var(--sc-dim-rgb), 0.55) !important;
    background-image: var(--tg-grain) !important;
}

/* ---------- 3. select2 下拉：同样改半透明磨砂（撤销实色化） ----------
   下拉浮在聊天内容上方，blur 采样到的是文字行，磨砂可读 */

.select2-dropdown {
    backdrop-filter: blur(20px) saturate(1.2) !important;
    -webkit-backdrop-filter: blur(20px) saturate(1.2) !important;
    background-color: rgba(var(--sc-surface-rgb), 0.80) !important;
}

/* ---------- 4. 弹窗：动画短（270ms），保留 blur ----------
   但遮罩层的双倍 blur 降到 1 倍——遮罩面积全屏，是隐形大户 */

.popup[open]::backdrop {
    backdrop-filter: blur(var(--SmartThemeBlurStrength)) !important;
    -webkit-backdrop-filter: blur(var(--SmartThemeBlurStrength)) !important;
}

/* ---------- 5. 移动端：保留磨砂（原实色化降级已撤销） ----------
   用户实测反馈：移动端完全无磨砂不可接受。
   平衡策略：blur 保留但降到 20px（移动 GPU 全屏采样成本可控），
   弹窗仅在动画瞬间实色化，打开后恢复磨砂 */

@media (hover: none) {

    /* 聊天区：保留磨砂玻璃，blur 降档（32 → 26）控制采样成本；
       saturate 同步降到 1.25——深色噪底上高 saturate 会放大绿/品红
       chroma（暗部 JPG/OLED 常见），酒红由 tint 色温保证不靠拉饱和。
       tint 降到 0.30 让壁纸细节透出来被 blur 抹动（磨砂可见的前提），
       再叠 TG 细噪点颗粒强化玻璃触感 */
    #chat {
        backdrop-filter: blur(26px) saturate(1.25) !important;
        -webkit-backdrop-filter: blur(26px) saturate(1.25) !important;
        background-color: rgba(var(--sc-dim-rgb), 0.30) !important;
        background-image: var(--tg-grain) !important;
    }

    /* 触控态只留 transform/opacity（GPU 合成），
       砍掉 background-color / box-shadow 过渡（强制重绘） */
    .menu_button,
    .menu_button:not(.disabled):not([disabled]):hover,
    .menu_button:not(.disabled):not([disabled]):active,
    .list-group-item,
    .options-content a,
    #extensionsMenu>div,
    .character_select,
    .tag,
    .select2-results .select2-results__option--selectable {
        transition-property: transform, opacity !important;
    }

    /* hover 白雾底改为纯 opacity 反馈 */
    .list-group-item:hover,
    .options-content a:hover,
    .character_select:hover {
        background-color: transparent !important;
        box-shadow: none !important;
    }

    /* 弹窗：动画期间（opening/closing 共约 570ms）实色化
       避免 pop-in 动画逐帧重 blur；动画结束即恢复磨砂 */
    .popup[opening],
    .popup[closing] {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        background-color: rgba(var(--sc-solid-rgb), 0.97) !important;
    }
}

/* ---------- 6. 桌面端保留的 blur 面（小而静态，成本可控） ----------
   #top-bar / #send_form：固定尺寸不动画，blur 快照可缓存
   #chat（桌面）：尺寸静态，滚动不触发背景重采样 */

/* ---------- 7. 滚动容器合成提示（仅限明确的小元素） ---------- */

.drawer-icon,
.mes_button,
.code-copy {
    will-change: transform;
}

/* ============================================================
   TG Glass — Round 9: 组件归纳层
   目标形态（TG Android 实机对照）：
   - 顶栏图标：统一弱化（TG 图标 54% 透明度规范），
     次要图标移动端隐藏
   - 欢迎按钮：TG 蓝实心胶囊（TG 空态按钮的官方形态）
   - 消息操作图标：悬停才显现（TG 无悬停时零 UI）
   - 输入区：齐平玻璃条 + 内嵌输入胶囊（TG Android 签名结构）
   - 聊天列表：文件大小/消息数删除、日期弱化、
     操作图标悬停显现、TG 蓝选中
   ============================================================ */

/* ---------- A. 顶栏图标：统一弱化 + 统一节奏 ---------- */

.drawer-toggle .drawer-icon {
    opacity: 0.50;
    font-size: 17px;
    transition: opacity 0.15s var(--tgEase), transform 0.15s var(--tgEase);
}

.drawer-toggle:hover .drawer-icon {
    opacity: 1;
}

.drawer-toggle:active .drawer-icon {
    transform: scale(0.88);
}

/* 抽屉锁定/解锁小按钮：同样弱化 */
.right_menu_button {
    opacity: 0.35;
    transition: opacity 0.15s var(--tgEase);
}

.right_menu_button:hover {
    opacity: 0.9;
}

/* ---------- B. 欢迎按钮：TG 蓝实心胶囊（扁平轻拟物） ----------
   无彩色光晕，仅中性小投影；按压翻转为凹陷 */

.custom-flex-container .drawer-opener.menu_button {
    border-radius: 22px !important;
    padding: 8px 24px !important;
    background-color: rgb(var(--sc-accent-rgb)) !important;
    border: none !important;
    color: var(--sc-accent-fg) !important;
    font-size: 13px !important;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.22) !important;
    transition: background-color 0.15s var(--tgEase), transform 0.15s var(--tgSpring), box-shadow 0.15s var(--tgEase);
}

.custom-flex-container .drawer-opener.menu_button:hover {
    filter: brightness(1.08);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.26) !important;
}

.custom-flex-container .drawer-opener.menu_button:active {
    transform: scale(0.97);
    box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.25) !important;
}

/* ---------- C. 消息操作图标：悬停显现（TG 零常驻 UI） ---------- */

.mes_buttons .mes_button {
    opacity: 0;
    transition: opacity 0.18s var(--tgEase);
}

.mes:hover .mes_buttons .mes_button {
    opacity: 0.55;
}

.mes_buttons .mes_button:hover {
    opacity: 1;
}

/* 触屏：保留低可见度（点击可达） */
@media (hover: none) {
    .mes_buttons .mes_button {
        opacity: 0.30;
    }
}

/* ---------- D. 输入区：扁平输入域 ----------
   圆角与容器节奏一致（10px），极淡描边 + 深底，无内阴影 */

#send_textarea {
    border-radius: 10px !important;
    background-color: rgba(0, 0, 0, 0.22) !important;
    border: 1px solid rgba(255, 255, 255, 0.10) !important;
    padding: 10px 16px !important;
    box-shadow: none !important;
    transition: border-color 0.15s var(--tgEase), background-color 0.15s var(--tgEase);
}

#send_textarea:focus {
    border-color: rgba(var(--sc-accent-rgb), 0.45) !important;
    background-color: rgba(0, 0, 0, 0.28) !important;
    outline: none !important;
}

/* 输入条两端图标：弱化 */
#options_button,
#rightSendForm .interactable {
    opacity: 0.60;
    transition: opacity 0.15s var(--tgEase), transform 0.15s var(--tgSpring);
}

#options_button:hover,
#rightSendForm .interactable:hover {
    opacity: 1;
}

/* 发送键：TG 蓝强调 */
#send_but,
.mes_send {
    color: rgb(var(--sc-accent-rgb));
}

/* ---------- E. 聊天列表（过去聊天）：扁平，零描边零倒角 ----------
   边缘分离 = 底色差（弹窗玻璃底上的深色块），悬停仅加深底色 */

.select_chat_block {
    background-color: rgba(0, 0, 0, 0.34) !important;
    border: none !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    transition: background-color 0.15s var(--tgEase);
}

.select_chat_block_wrapper:hover .select_chat_block {
    background-color: rgba(0, 0, 0, 0.42) !important;
}

/* 文件大小 / 消息数：删除（TG 列表没有这些） */
.chat_file_size,
.chat_messages_num {
    display: none !important;
}

/* 日期：右侧弱化小字（TG 日期形态） */
.chat_messages_date {
    color: rgba(255, 255, 255, 0.40) !important;
    font-size: 11px !important;
}

/* 名称：TG 主文本 */
.select_chat_block_filename {
    font-size: 13px !important;
    color: rgba(255, 255, 255, 0.92) !important;
}

/* 预览消息：灰色单行省略 */
.select_chat_block_mes {
    color: rgba(255, 255, 255, 0.48) !important;
    font-size: 12px !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

/* 操作图标（重命名/导出/删除）：悬停才显现 */
.select_chat_actions,
.renameChatButton {
    opacity: 0;
    transition: opacity 0.15s var(--tgEase);
}

.select_chat_block_wrapper:hover .select_chat_actions,
.select_chat_block_wrapper:hover .renameChatButton {
    opacity: 0.55;
}

.select_chat_actions div:hover,
.renameChatButton:hover {
    opacity: 1;
}

/* 当前聊天：TG 蓝选中态（纯底色着色，扁平） */
.select_chat_block[highlight] {
    background-color: rgba(var(--sc-accent-rgb), 0.16) !important;
}

/* 列表项间距：边框后留呼吸空隙 */
.welcomeRecent .recentChatList {
    gap: 6px !important;
}

/* 头像圆形 */
.select_chat_block .avatar,
.select_chat_block_wrapper .avatar {
    border-radius: 50% !important;
}

/* ---------- E2. 欢迎页最近聊天（welcomePanel，类名与过去聊天面板不同） ----------
   Round 9 误用了 select_chat_block 的类名导致未生效，这里用正确选择器：
   文件大小/消息数删除、日期弱化、操作图标悬停显现、单行省略 */

.recentChat .fileSize,
.recentChat .counterBlock {
    display: none !important;
}

.recentChat .chatActions {
    opacity: 0;
    transition: opacity 0.15s var(--tgEase);
}

.recentChat:hover .chatActions {
    opacity: 0.55;
}

.recentChat .chatActions .menu_button:hover {
    opacity: 1;
}

.recentChat .chatDate {
    color: rgba(255, 255, 255, 0.40) !important;
    font-size: 11px !important;
}

.recentChat .chatName {
    font-size: 13px !important;
    color: rgba(255, 255, 255, 0.92) !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.recentChat .chatMessage {
    color: rgba(255, 255, 255, 0.48) !important;
    font-size: 12px !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---------- E3. 最近聊天列表项：扁平 + 模糊度差分 ----------
   零描边零倒角零投影：边缘分离完全靠模糊度差分——
   列表项自身 blur(42px) 强于外围（面板 32px），叠加更深底色，
   在丝绸背景上形成干净的磨砂视窗边界；边框内模糊加重保可读性 */

.recentChat {
    background-color: rgba(0, 0, 0, 0.40) !important;
    border: none !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    backdrop-filter: blur(42px) saturate(1.4) !important;
    -webkit-backdrop-filter: blur(42px) saturate(1.4) !important;
    transition: background-color 0.15s var(--tgEase);
}

.recentChat:hover {
    background-color: rgba(0, 0, 0, 0.48) !important;
}

.recentChat .avatar {
    border-radius: 50% !important;
    border: 1px solid rgba(255, 255, 255, 0.18);
}

/* 文字可读性：主标题加保护阴影，副标题提亮 */
.recentChat .chatName {
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.55);
}

.recentChat .chatMessage {
    color: rgba(255, 255, 255, 0.64) !important;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.50);
}

/* ---------- F. 消息元信息弱化 ---------- */

.mes .mes_date {
    color: rgba(255, 255, 255, 0.35);
    font-size: 11px;
}

.mes .ch_name {
    font-size: 13px;
}

/* ---------- H0. 光效防裁切 / 防遮挡（全站） ----------
   光晕被吃掉有三类成因，逐一对症：
   ① 祖先 overflow 裁切 box-shadow → 换 clip-path / 放开容器
   ② 后画的兄弟元素（实底）盖住前面的光晕 → 递减 z-index 抬画序
   ③ 滚动容器边框把光晕切出硬边 → clip-margin 放行少量像素 */

/* ① 消息块：clip-path 替代 overflow:hidden（阴影不参与布局不触发
      滚动）。纵向 -32px 给 hover 光晕（0 6px 20px ≈ 27px）留足
      呼吸空间；横向保持收紧防长行撑破布局（pre/code 自带横滚）。 */
.mes_block {
    overflow: visible !important;
    clip-path: inset(-32px 0 -32px 0);
}

/* 移动端：#chat 全宽且自身就是裁切边界（切线在屏幕外不可见），
      横向放行让胶囊光晕一直透到屏幕边 */
@media screen and (max-width: 1000px) {
    .mes_block {
        clip-path: inset(-32px -24px -32px -24px) !important;
    }
}

/* ② 欢迎页胶囊按钮组：实底按钮相邻仅 3px，前面按钮的光晕会被
      后面按钮的实体盖出一条硬切线。递减 z-index 让前面的按钮
      画在上面 → 光晕像光一样洒落在相邻按钮上 */
.custom-flex-container > * {
    position: relative;
}

.custom-flex-container > *:nth-last-child(1) { z-index: 1; }
.custom-flex-container > *:nth-last-child(2) { z-index: 2; }
.custom-flex-container > *:nth-last-child(3) { z-index: 3; }
.custom-flex-container > *:nth-last-child(4) { z-index: 4; }
.custom-flex-container > *:nth-last-child(5) { z-index: 5; }
.custom-flex-container > *:nth-last-child(6) { z-index: 6; }

/* ③ 输入区玻璃条 30px 柔影被 #sheld{overflow-x:hidden} 四边硬切
      （左侧可见竖向切缝、底部切掉光带）。#chat 自身就是滚动裁切
      容器，sheld 无需再裁，body 还有兜底 */
#sheld {
    overflow: visible !important;
}

/* ④ 顶栏下坠阴影被 #chat 吃掉：ST 原生 #top-bar 在 DOM 中先于
      #sheld（同为 absolute / z-index auto），#chat 的 backdrop-filter
      会把画在它下面的顶栏阴影重新采样掉 → 顶栏贴着聊天区没有
      深度感。抬高层叠让阴影画在聊天玻璃之上 */
#top-bar {
    z-index: 3 !important;
}

/* 最近聊天行内图标按钮的微光：允许 10px 泄出再裁
      （文字省略由 .chatName/.chatMessage 自身处理，不受影响；
      ST 原规则特异性高，需 !important 压制） */
.recentChatInfo {
    overflow: clip !important;
    overflow-clip-margin: 10px;
}

/* 代码块/引用块：长行内部横向滚动（不撑破布局） */
.mes_text pre,
.mes_text code,
.mes_reasoning pre {
    overflow-x: auto;
    overflow-y: visible;
    max-width: 100%;
}

/* ---------- H. 手风琴（扩展面板/用户设置折叠项）：玻璃化 ----------
   ST 原生是白灰黑塑料渐变 + brightness(150%) hover，改为玻璃材质 */

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: linear-gradient(348deg,
            rgba(255, 255, 255, 0.05) 2%,
            rgba(255, 255, 255, 0.02) 10%,
            rgba(var(--sc-dim-rgb), 0.45) 95%,
            rgba(var(--sc-accent-rgb), 0.45) 100%) !important;
    border: 1px solid var(--tgStrokeBottom) !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    transition: border-color 0.15s var(--tgEase),
        background-image 0.15s var(--tgEase);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader.inline-drawer-header:hover {
    filter: none;
    border-color: rgba(var(--sc-accent-rgb), 0.40) !important;
}

/* 折叠箭头图标：弱化 → 主色 */
.inline-drawer-icon,
.custom-drawer-icon {
    filter: none !important;
    opacity: 0.55;
    font-size: calc(var(--mainFontSize) * 1.2);
    transition: opacity 0.15s var(--tgEase), transform 0.15s var(--tgSpring),
        color 0.15s var(--tgEase);
}

.inline-drawer-toggle:hover .inline-drawer-icon,
.inline-drawer-toggle:hover .custom-drawer-icon {
    opacity: 1;
    color: rgb(var(--sc-accent-rgb));
}

.inline-drawer-toggle:active .inline-drawer-icon,
.inline-drawer-toggle:active .custom-drawer-icon {
    transform: scale(0.88);
}

/* 手风琴内容面板：暗面玻璃 */
.standoutHeader~.inline-drawer-content {
    background-color: rgba(var(--sc-dim-rgb), 0.35) !important;
    border: 1px solid var(--tgStrokeBottom) !important;
}

/* 兜底：所有 FA 图标按钮 hover 主色化（消灭残余蓝） */
.mes_button:hover,
.extraMesButtons>div:hover,
.fa-solid.interactable:hover,
.fa-regular.interactable:hover {
    color: rgb(var(--sc-accent-rgb));
}

/* API 状态按钮 hover：白雾玻璃反馈（替代 ST 原生绿色 --active） */
.menu_button.api_button:hover {
    background-color: rgba(255, 255, 255, 0.08) !important;
}

/* ---------- G. 移动端：图标弱化（不隐藏，保持原版可用性） ---------- */

@media screen and (max-width: 1000px) {

    .drawer-toggle .drawer-icon {
        font-size: 16px;
        opacity: 0.55;
    }
}
